import React from 'react';
import { AlertOctagon } from '@hexa-ui/icons';
import { render, screen, fireEvent } from '@testing-library/react';
import IconButton from './IconButton';

describe('IconButton', () => {
  it('should render', () => {
    render(<IconButton icon={AlertOctagon} data-testid="IconButton" />);
    expect(screen.getByTestId('IconButton')).toBeInTheDocument();
  });

  it('should render with size prop as large', () => {
    render(<IconButton icon={AlertOctagon} data-testid="IconButton" size="large" />);
    expect(screen.getByTestId('IconButton')).toBeInTheDocument();
  });

  it('should render with size prop as tiny and variant inherit', () => {
    render(
      <IconButton icon={AlertOctagon} data-testid="IconButton" size="tiny" variant="inherit" />
    );
    expect(screen.getByTestId('IconButton')).toBeInTheDocument();
  });
  it('should render with size prop as tiny and variant terciary', () => {
    render(
      <IconButton icon={AlertOctagon} data-testid="IconButton" size="tiny" variant="terciary" />
    );
    expect(screen.getByTestId('IconButton')).toBeInTheDocument();
  });
  it('should render with size prop as small', () => {
    render(<IconButton icon={AlertOctagon} data-testid="IconButton" size="small" />);
    expect(screen.getByTestId('IconButton')).toBeInTheDocument();
  });

  it('should render with variant as secondary', () => {
    render(<IconButton icon={AlertOctagon} data-testid="IconButton" variant="secondary" />);
    expect(screen.getByTestId('IconButton')).toBeInTheDocument();
  });

  it('should render with variant as tertiary', () => {
    render(<IconButton icon={AlertOctagon} data-testid="IconButton" variant="tertiary" />);
    expect(screen.getByTestId('IconButton')).toBeInTheDocument();
  });

  it('should render with variant as inherit', () => {
    render(<IconButton icon={AlertOctagon} data-testid="IconButton" variant="inherit" />);
    expect(screen.getByTestId('IconButton')).toBeInTheDocument();
  });

  it('should render with loading prop as true', () => {
    render(
      <IconButton
        icon={AlertOctagon}
        data-testid="IconButton"
        loading
        size="large"
        variant="secondary"
      />
    );
    expect(screen.getByTestId('LoadingDots')).toBeInTheDocument();
  });

  it('should render with loading prop as true, size tiny and variant inherit', () => {
    render(
      <IconButton
        icon={AlertOctagon}
        data-testid="IconButton"
        loading
        size="tiny"
        variant="inherit"
      />
    );
    expect(screen.getByTestId('LoadingDots')).toBeInTheDocument();
  });
  it('should render with loading prop as true, size tiny and variant terciary', () => {
    render(
      <IconButton
        icon={AlertOctagon}
        data-testid="IconButton"
        loading
        size="tiny"
        variant="terciary"
      />
    );
    expect(screen.getByTestId('LoadingDots')).toBeInTheDocument();
  });
  it('should render with loading prop as true and size as medium', () => {
    render(
      <IconButton
        icon={AlertOctagon}
        data-testid="IconButton"
        loading
        size="medium"
        variant="secondary"
      />
    );
    expect(screen.getByTestId('LoadingDots')).toBeInTheDocument();
  });

  it('should render with loading prop as true and size as medium with variant primary', () => {
    render(
      <IconButton
        icon={AlertOctagon}
        data-testid="IconButton"
        loading
        size="medium"
        variant="primary"
      />
    );
    expect(screen.getByTestId('LoadingDots')).toBeInTheDocument();
  });

  it('should render with elevation prop as true', () => {
    render(<IconButton icon={AlertOctagon} data-testid="IconButton" elevation />);
    expect(screen.getByTestId('IconButton')).toBeInTheDocument();
  });

  it('should call onClick function when clicked', () => {
    const mockedFunc = jest.fn();
    render(
      <IconButton icon={AlertOctagon} data-testid="IconButtonClick" onClick={() => mockedFunc()} />
    );
    const button = screen.getByTestId('IconButtonClick');
    fireEvent.click(button);
    expect(mockedFunc).toBeCalled();
  });

  it('should not call onClick function when clicked when disabled is true', () => {
    const mockedFunc = jest.fn();
    render(
      <IconButton
        icon={AlertOctagon}
        data-testid="IconButtonDisabled"
        onClick={() => mockedFunc()}
        disabled
        className="styled-class"
      />
    );
    const button = screen.getByTestId('IconButtonDisabled');
    fireEvent.click(button);
    expect(mockedFunc).not.toBeCalled();
  });
});
